import React from "react";
import type { Meta } from "@storybook/react";
import * as AirbusIcons from "@airbus/icons/react";
import Home from "@material-design-icons/svg/filled/home.svg?react";
import Settings from "@material-design-icons/svg/filled/settings.svg?react";
import Delete from "@material-design-icons/svg/filled/delete.svg?react";
import Room from "@material-design-icons/svg/filled/room.svg?react";
import Feedback from "@material-design-icons/svg/filled/feedback.svg?react";
import HomeOutlined from "@material-design-icons/svg/outlined/home.svg?react";
import SettingsOutlined from "@material-design-icons/svg/outlined/settings.svg?react";
import DeleteOutlined from "@material-design-icons/svg/outlined/delete.svg?react";
import RoomOutlined from "@material-design-icons/svg/outlined/room.svg?react";
import FeedbackOutlined from "@material-design-icons/svg/outlined/feedback.svg?react";
import Typography from "../components/Typography";
import { IconButton, Tooltip } from "../components";

const meta: Meta = {
  title: "General/Visual Styles/Icons",
};
export default meta;

export const Airbus = {
  render: () => {
    const iconNames = Object.keys(AirbusIcons);
    return (
      <>
        <Typography variant="small" color="secondary">
          Mouse over icons to see names. Click to copy to the clipboard.
        </Typography>
        <br />
        <div className="icons-list">
          {iconNames.map((iconName) => {
            const AirbusSVGIcon = (AirbusIcons as any)[iconName];
            const copyToClipboard = (value: string) => {
              navigator.clipboard.writeText(value);
              window.alert(`Copied to clipboard: "${value}"`);
            };
            return (
              <Tooltip label={iconName} key={iconName} enterDelay={0} exitDelay={0}>
                <IconButton variant="ghost" size="large" onClick={() => copyToClipboard(iconName)}>
                  <AirbusSVGIcon />
                </IconButton>
              </Tooltip>
            );
          })}
        </div>
      </>
    );
  },
};

export const Material = {
  render: () => (
    <>
      <div className="icons-list">
        <Home />
        <Settings />
        <Delete />
        <Room />
        <Feedback />
      </div>
      <div className="icons-list">
        <HomeOutlined />
        <SettingsOutlined />
        <DeleteOutlined />
        <RoomOutlined />
        <FeedbackOutlined />
      </div>
    </>
  ),
};
